CREATE TABLE work_nodes (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), archived INTEGER NOT NULL CHECK(archived IN(0,1)), "branch_id" TEXT NOT NULL, "kind" TEXT NOT NULL, "granularity" TEXT NOT NULL, "title" TEXT NOT NULL, "objective" TEXT NOT NULL, "acceptance_criteria" TEXT NOT NULL CHECK(json_valid("acceptance_criteria")), "status" TEXT NOT NULL, "owner" TEXT NOT NULL CHECK(json_valid("owner")), "capability_requirements" TEXT NOT NULL CHECK(json_valid("capability_requirements")), "context_policy_id" TEXT NOT NULL, "budget" TEXT NOT NULL CHECK(json_valid("budget")), "created_by" TEXT NOT NULL CHECK(json_valid("created_by")), UNIQUE(id,project_id), FOREIGN KEY("branch_id",project_id) REFERENCES branches(id,project_id) DEFERRABLE INITIALLY DEFERRED, CHECK(granularity IN ('atomic','composite')), CHECK(status IN ('proposed','ready','running','blocked','waiting_for_human','succeeded','failed','cancelled','superseded')));
CREATE INDEX work_nodes_project ON work_nodes(project_id);
CREATE TABLE work_edges (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), archived INTEGER NOT NULL CHECK(archived IN(0,1)), "branch_id" TEXT NOT NULL, "from" TEXT NOT NULL, "to" TEXT NOT NULL, "kind" TEXT NOT NULL, UNIQUE(id,project_id), FOREIGN KEY("branch_id",project_id) REFERENCES branches(id,project_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("from",project_id) REFERENCES work_nodes(id,project_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("to",project_id) REFERENCES work_nodes(id,project_id) DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX work_edges_project ON work_edges(project_id);
CREATE TABLE plan_revisions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), archived INTEGER NOT NULL CHECK(archived IN(0,1)), "branch_id" TEXT NOT NULL, "parent_revision_id" TEXT, "nodes" TEXT NOT NULL CHECK(json_valid("nodes")), "edges" TEXT NOT NULL CHECK(json_valid("edges")), "reason" TEXT NOT NULL, "created_by" TEXT NOT NULL CHECK(json_valid("created_by")), UNIQUE(id,project_id), FOREIGN KEY("branch_id",project_id) REFERENCES branches(id,project_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("parent_revision_id",project_id) REFERENCES plan_revisions(id,project_id) DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX plan_revisions_project ON plan_revisions(project_id);
CREATE TRIGGER plan_revisions_no_update BEFORE UPDATE ON plan_revisions BEGIN SELECT RAISE(ABORT,'immutable runtime record'); END;
CREATE TRIGGER plan_revisions_no_delete BEFORE DELETE ON plan_revisions BEGIN SELECT RAISE(ABORT,'immutable runtime record'); END;
CREATE TABLE branches (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), archived INTEGER NOT NULL CHECK(archived IN(0,1)), "name" TEXT NOT NULL, "parent_branch_id" TEXT, "base_checkpoint_id" TEXT, "head_revision_id" TEXT, UNIQUE(id,project_id), FOREIGN KEY("parent_branch_id",project_id) REFERENCES branches(id,project_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("base_checkpoint_id",project_id) REFERENCES checkpoints(id,project_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("head_revision_id",project_id) REFERENCES plan_revisions(id,project_id) DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX branches_project ON branches(project_id);
CREATE TABLE checkpoints (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), archived INTEGER NOT NULL CHECK(archived IN(0,1)), "run_id" TEXT, "work_node_id" TEXT, "branch_id" TEXT NOT NULL, "plan_revision_id" TEXT NOT NULL, "context_snapshot_id" TEXT, "boundary" TEXT NOT NULL, "execution_state" TEXT NOT NULL CHECK(json_valid("execution_state")), UNIQUE(id,project_id), FOREIGN KEY("run_id",project_id) REFERENCES runs(id,project_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("work_node_id",project_id) REFERENCES work_nodes(id,project_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("branch_id",project_id) REFERENCES branches(id,project_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("plan_revision_id",project_id) REFERENCES plan_revisions(id,project_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("context_snapshot_id",project_id) REFERENCES context_snapshots(id,project_id) DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX checkpoints_project ON checkpoints(project_id);
CREATE TRIGGER checkpoints_no_update BEFORE UPDATE ON checkpoints BEGIN SELECT RAISE(ABORT,'immutable runtime record'); END;
CREATE TRIGGER checkpoints_no_delete BEFORE DELETE ON checkpoints BEGIN SELECT RAISE(ABORT,'immutable runtime record'); END;
CREATE TABLE context_snapshots (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), archived INTEGER NOT NULL CHECK(archived IN(0,1)), "work_node_id" TEXT NOT NULL, "plan_revision_id" TEXT NOT NULL, "entries" TEXT NOT NULL CHECK(json_valid("entries")), "process_memory_ids" TEXT NOT NULL CHECK(json_valid("process_memory_ids")), "instruction_version" TEXT NOT NULL, "skill_versions" TEXT NOT NULL CHECK(json_valid("skill_versions")), "budget_tokens" INTEGER NOT NULL CHECK("budget_tokens">=0), "estimated_tokens" INTEGER NOT NULL CHECK("estimated_tokens">=0), "estimation_method" TEXT NOT NULL, UNIQUE(id,project_id), FOREIGN KEY("work_node_id",project_id) REFERENCES work_nodes(id,project_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("plan_revision_id",project_id) REFERENCES plan_revisions(id,project_id) DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX context_snapshots_project ON context_snapshots(project_id);
CREATE TRIGGER context_snapshots_no_update BEFORE UPDATE ON context_snapshots BEGIN SELECT RAISE(ABORT,'immutable runtime record'); END;
CREATE TRIGGER context_snapshots_no_delete BEFORE DELETE ON context_snapshots BEGIN SELECT RAISE(ABORT,'immutable runtime record'); END;
CREATE TABLE process_memories (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), archived INTEGER NOT NULL CHECK(archived IN(0,1)), "namespace" TEXT NOT NULL, "work_node_id" TEXT, "content" TEXT NOT NULL, "created_by" TEXT NOT NULL CHECK(json_valid("created_by")), UNIQUE(id,project_id), FOREIGN KEY("work_node_id",project_id) REFERENCES work_nodes(id,project_id) DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX process_memories_project ON process_memories(project_id);
CREATE TRIGGER process_memories_no_update BEFORE UPDATE ON process_memories BEGIN SELECT RAISE(ABORT,'immutable runtime record'); END;
CREATE TRIGGER process_memories_no_delete BEFORE DELETE ON process_memories BEGIN SELECT RAISE(ABORT,'immutable runtime record'); END;
CREATE TABLE execution_bindings (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), archived INTEGER NOT NULL CHECK(archived IN(0,1)), "work_node_id" TEXT NOT NULL, "branch_id" TEXT NOT NULL, "plan_revision_id" TEXT NOT NULL, UNIQUE(id,project_id), FOREIGN KEY("id",project_id) REFERENCES runs(id,project_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("work_node_id",project_id) REFERENCES work_nodes(id,project_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("branch_id",project_id) REFERENCES branches(id,project_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("plan_revision_id",project_id) REFERENCES plan_revisions(id,project_id) DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX execution_bindings_project ON execution_bindings(project_id);
CREATE TRIGGER execution_bindings_no_update BEFORE UPDATE ON execution_bindings BEGIN SELECT RAISE(ABORT,'immutable runtime record'); END;
CREATE TRIGGER execution_bindings_no_delete BEFORE DELETE ON execution_bindings BEGIN SELECT RAISE(ABORT,'immutable runtime record'); END;
CREATE TABLE model_invocations (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), archived INTEGER NOT NULL CHECK(archived IN(0,1)), "run_id" TEXT NOT NULL, "work_node_id" TEXT NOT NULL, "context_snapshot_id" TEXT NOT NULL, "provider" TEXT NOT NULL, "model" TEXT NOT NULL, "model_revision" TEXT NOT NULL, "runtime" TEXT NOT NULL, "instruction_version" TEXT NOT NULL, "output_schema" TEXT NOT NULL CHECK(json_valid("output_schema")), "started_at" TEXT NOT NULL, "finished_at" TEXT, "latency_ms" INTEGER CHECK("latency_ms">=0), "status" TEXT NOT NULL, "usage" TEXT NOT NULL CHECK(json_valid("usage")), "metadata" TEXT NOT NULL CHECK(json_valid("metadata")), UNIQUE(id,project_id), FOREIGN KEY("run_id",project_id) REFERENCES runs(id,project_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("work_node_id",project_id) REFERENCES work_nodes(id,project_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("context_snapshot_id",project_id) REFERENCES context_snapshots(id,project_id) DEFERRABLE INITIALLY DEFERRED, CHECK(status IN ('running','succeeded','failed','cancelled')));
CREATE INDEX model_invocations_project ON model_invocations(project_id);
CREATE TABLE tool_invocations (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), archived INTEGER NOT NULL CHECK(archived IN(0,1)), "run_id" TEXT NOT NULL, "work_node_id" TEXT NOT NULL, "tool" TEXT NOT NULL, "tool_version" TEXT NOT NULL, "input_artifacts" TEXT NOT NULL CHECK(json_valid("input_artifacts")), "output_artifacts" TEXT NOT NULL CHECK(json_valid("output_artifacts")), "started_at" TEXT NOT NULL, "finished_at" TEXT, "status" TEXT NOT NULL, "error_code" TEXT, UNIQUE(id,project_id), FOREIGN KEY("run_id",project_id) REFERENCES runs(id,project_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("work_node_id",project_id) REFERENCES work_nodes(id,project_id) DEFERRABLE INITIALLY DEFERRED, CHECK(status IN ('running','succeeded','failed','cancelled')));
CREATE INDEX tool_invocations_project ON tool_invocations(project_id);
CREATE TABLE candidate_claims (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), archived INTEGER NOT NULL CHECK(archived IN(0,1)), "paper_id" TEXT NOT NULL, "source_id" TEXT NOT NULL, "text" TEXT NOT NULL, "source_quote" TEXT NOT NULL, "location" TEXT NOT NULL CHECK(json_valid("location")), "promoted_claim_id" TEXT, UNIQUE(id,project_id), FOREIGN KEY("paper_id",project_id) REFERENCES papers(id,project_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("source_id",project_id) REFERENCES sources(id,project_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("promoted_claim_id",project_id) REFERENCES claims(id,project_id) DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX candidate_claims_project ON candidate_claims(project_id);

CREATE VIRTUAL TABLE research_fts USING fts5(project_id UNINDEXED,kind UNINDEXED,entity_id UNINDEXED,body);
INSERT INTO research_fts SELECT project_id,'claim',id,text FROM claims;
CREATE TRIGGER claims_fts_insert AFTER INSERT ON claims BEGIN INSERT INTO research_fts(project_id,kind,entity_id,body) VALUES(new.project_id,'claim',new.id,new.text); END;
CREATE TRIGGER claims_fts_update AFTER UPDATE ON claims BEGIN DELETE FROM research_fts WHERE entity_id=old.id; INSERT INTO research_fts(project_id,kind,entity_id,body) VALUES(new.project_id,'claim',new.id,new.text); END;
CREATE TRIGGER claims_fts_delete AFTER DELETE ON claims BEGIN DELETE FROM research_fts WHERE entity_id=old.id; END;
INSERT INTO research_fts SELECT project_id,'paper',id,title || ' ' || abstract_text FROM papers;
CREATE TRIGGER papers_fts_insert AFTER INSERT ON papers BEGIN INSERT INTO research_fts(project_id,kind,entity_id,body) VALUES(new.project_id,'paper',new.id,new.title || ' ' || new.abstract_text); END;
CREATE TRIGGER papers_fts_update AFTER UPDATE ON papers BEGIN DELETE FROM research_fts WHERE entity_id=old.id; INSERT INTO research_fts(project_id,kind,entity_id,body) VALUES(new.project_id,'paper',new.id,new.title || ' ' || new.abstract_text); END;
CREATE TRIGGER papers_fts_delete AFTER DELETE ON papers BEGIN DELETE FROM research_fts WHERE entity_id=old.id; END;
INSERT INTO research_fts SELECT project_id,'question',id,title || ' ' || description FROM research_questions;
CREATE TRIGGER research_questions_fts_insert AFTER INSERT ON research_questions BEGIN INSERT INTO research_fts(project_id,kind,entity_id,body) VALUES(new.project_id,'question',new.id,new.title || ' ' || new.description); END;
CREATE TRIGGER research_questions_fts_update AFTER UPDATE ON research_questions BEGIN DELETE FROM research_fts WHERE entity_id=old.id; INSERT INTO research_fts(project_id,kind,entity_id,body) VALUES(new.project_id,'question',new.id,new.title || ' ' || new.description); END;
CREATE TRIGGER research_questions_fts_delete AFTER DELETE ON research_questions BEGIN DELETE FROM research_fts WHERE entity_id=old.id; END;
